package dev.mcc.core;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.zip.*;
import static org.junit.jupiter.api.Assertions.*;

class PluginLifecycleTest {
    @TempDir Path root;
    private Path data;
    private final List<Map<String,Object>> runtime=new ArrayList<>();
    private PluginLifecycle lifecycle(boolean hook)throws Exception {Files.createDirectories(root.resolve("plugins"));data=Files.createDirectories(root.resolve("plugins/MinecraftControlCenter"));Files.createDirectories(data.resolve("kernel-profiles"));if(!Files.exists(data.resolve("kernel-profiles/runtime.lock")))Files.createFile(data.resolve("kernel-profiles/runtime.lock"));Files.createDirectories(root.resolve(".mcc-launcher"));if(!Files.exists(root.resolve(".mcc-launcher/daemon.lock")))Files.createFile(root.resolve(".mcc-launcher/daemon.lock"));return new PluginLifecycle(data,()->List.copyOf(runtime),()->hook);}
    private Path jar(String file,String name,String extra)throws Exception {Path path=root.resolve("plugins").resolve(file);try(ZipOutputStream zip=new ZipOutputStream(Files.newOutputStream(path))){zip.putNextEntry(new ZipEntry("plugin.yml"));zip.write(("name: "+name+"\nversion: '1.0'\nmain: test.Main\n"+extra).getBytes(StandardCharsets.UTF_8));zip.closeEntry();zip.putNextEntry(new ZipEntry("test/Main.class"));zip.write(new byte[]{1,2,3});zip.closeEntry();}return path;}
    private Map<String,Object> remove(PluginLifecycle lifecycle,String name)throws Exception {Map<String,Object> plan=lifecycle.plan(name,"owner-session-digest");return lifecycle.remove(plan.get("planId").toString(),"owner-session-digest",()->true);}
    @SuppressWarnings("unchecked") private List<Map<String,Object>> rows(Map<String,Object> value,String key){return (List<Map<String,Object>>)value.get(key);}

    @Test void liveRemovalIsInertOfflineMovesExactBytesAndRestoreKeepsIndependentBackup()throws Exception {
        PluginLifecycle lifecycle=lifecycle(true);Path original=jar("AdvancedBanZ.jar","AdvancedBanZ","");byte[] bytes=Files.readAllBytes(original);Path config=Files.createDirectories(root.resolve("plugins/AdvancedBanZ")).resolve("config.yml");Files.writeString(config,"manual: keep\n");runtime.add(Map.of("name","AdvancedBanZ","version","1.0","enabled",true));
        Map<String,Object> operation=remove(lifecycle,"AdvancedBanZ");assertEquals("pending-removal",operation.get("status"));assertArrayEquals(bytes,Files.readAllBytes(original));assertTrue(Boolean.TRUE.equals(rows(lifecycle.list(),"plugins").getFirst().get("loaded")));
        assertEquals(1,PluginMaintenanceBootstrap.runOffline(root,data).get("removed"));assertFalse(Files.exists(original));assertEquals("manual: keep\n",Files.readString(config));runtime.clear();
        String id=operation.get("removalId").toString();Map<String,Object> restored=lifecycle.restore(id,"new-owner-session",()->true);assertEquals("restored-pending-restart",restored.get("status"));assertArrayEquals(bytes,Files.readAllBytes(original));Path backup=data.resolve("plugin-quarantine").resolve(id).resolve("plugin.jar");assertArrayEquals(bytes,Files.readAllBytes(backup));Files.writeString(original,"external change");assertArrayEquals(bytes,Files.readAllBytes(backup));
    }
    @Test void undoBeforeRestartCancelsWithoutMovingTheJar()throws Exception {PluginLifecycle lifecycle=lifecycle(true);Path original=jar("example.jar","Example","");byte[] bytes=Files.readAllBytes(original);Map<String,Object> operation=remove(lifecycle,"Example");assertEquals("cancelled",lifecycle.restore(operation.get("removalId").toString(),"owner",()->true).get("status"));assertEquals(0,PluginMaintenanceBootstrap.runOffline(root,data).get("removed"));assertArrayEquals(bytes,Files.readAllBytes(original));}
    @Test void hardDependenciesAndProvidesAliasesBlockRemovalButSoftDependenciesDoNot()throws Exception {PluginLifecycle lifecycle=lifecycle(true);jar("provider.jar","Provider","provides: [Alias]\n");jar("consumer.jar","Consumer","depend: [Alias]\n");assertThrows(PluginLifecycle.Conflict.class,()->lifecycle.plan("Provider","owner"));Files.delete(root.resolve("plugins/consumer.jar"));jar("consumer.jar","Consumer","softdepend: [Alias]\n");assertDoesNotThrow(()->lifecycle.plan("Provider","owner"));}
    @Test void paperServerAndBootstrapRequiredDependenciesBlockRemoval()throws Exception {PluginLifecycle lifecycle=lifecycle(true);jar("provider.jar","Provider","");Path consumer=root.resolve("plugins/consumer.jar");try(ZipOutputStream zip=new ZipOutputStream(Files.newOutputStream(consumer))){zip.putNextEntry(new ZipEntry("paper-plugin.yml"));zip.write("name: Consumer\nversion: '1'\nmain: test.Main\ndependencies:\n  server:\n    Provider:\n      required: true\n".getBytes(StandardCharsets.UTF_8));zip.closeEntry();zip.putNextEntry(new ZipEntry("test/Main.class"));zip.write(1);zip.closeEntry();}assertThrows(PluginLifecycle.Conflict.class,()->lifecycle.plan("Provider","owner"));}
    @Test void selfProtectionIncludesProvidesAndOfflineTamperedRequests()throws Exception {PluginLifecycle lifecycle=lifecycle(true);jar("fake.jar","Other","provides: [MinecraftControlCenter]\n");assertThrows(SecurityException.class,()->lifecycle.plan("Other","owner"));assertFalse(Boolean.TRUE.equals(rows(lifecycle.list(),"plugins").getFirst().get("canRemove")));}
    @Test void noHookBlocksRemovalAndCannotUnloadAnyLivePlugin()throws Exception {PluginLifecycle lifecycle=lifecycle(false);jar("example.jar","Example","");assertFalse(Boolean.TRUE.equals(lifecycle.list().get("prelaunchSupported")));assertThrows(IllegalStateException.class,()->lifecycle.plan("Example","owner"));assertTrue(Files.exists(root.resolve("plugins/example.jar")));}
    @Test void authorityAndActorAreCheckedBeforePersistentIntent()throws Exception {PluginLifecycle lifecycle=lifecycle(true);jar("example.jar","Example","");Map<String,Object> plan=lifecycle.plan("Example","owner-a");assertThrows(SecurityException.class,()->lifecycle.remove(plan.get("planId").toString(),"owner-b",()->true));assertThrows(SecurityException.class,()->lifecycle.remove(plan.get("planId").toString(),"owner-a",()->false));assertTrue(rows(lifecycle.list(),"removals").isEmpty());}
    @Test void changedBytesAndNewDependentInvalidatePlanAndOfflineGuard()throws Exception {PluginLifecycle lifecycle=lifecycle(true);Path target=jar("example.jar","Example","");Map<String,Object> plan=lifecycle.plan("Example","owner");jar("example.jar","Example","description: changed\n");assertThrows(PluginLifecycle.Conflict.class,()->lifecycle.remove(plan.get("planId").toString(),"owner",()->true));Map<String,Object> operation=remove(lifecycle,"Example");jar("consumer.jar","Consumer","depend: [Example]\n");assertThrows(PluginLifecycle.Conflict.class,()->PluginMaintenanceBootstrap.runOffline(root,data));assertTrue(Files.exists(target));assertEquals("pending-removal",rows(lifecycle.list(),"removals").getFirst().get("status"));}
    @Test void interruptedOfflineMoveIsRecoveredWithExactPrivateBytes()throws Exception {PluginLifecycle lifecycle=lifecycle(true);Path target=jar("example.jar","Example","");Map<String,Object> operation=remove(lifecycle,"Example");Path retained=data.resolve("plugin-quarantine").resolve(operation.get("removalId").toString()).resolve("plugin.jar");Files.move(target,retained);assertEquals(1,PluginMaintenanceBootstrap.runOffline(root,data).get("removed"));assertEquals("removed",rows(lifecycle.list(),"removals").getFirst().get("status"));assertTrue(Files.exists(retained));}
    @Test void restorationRejectsOccupiedIdentityAndUnsatisfiedDependencies()throws Exception {PluginLifecycle lifecycle=lifecycle(true);jar("provider.jar","Provider","");jar("consumer.jar","Consumer","depend: [Provider]\n");Map<String,Object> operation=remove(lifecycle,"Consumer");PluginMaintenanceBootstrap.runOffline(root,data);String id=operation.get("removalId").toString();Files.delete(root.resolve("plugins/provider.jar"));assertThrows(PluginLifecycle.Conflict.class,()->lifecycle.restore(id,"owner",()->true));jar("provider.jar","Provider","");jar("other.jar","Consumer","");assertThrows(PluginLifecycle.Conflict.class,()->lifecycle.restore(id,"owner",()->true));assertFalse(Files.exists(root.resolve("plugins/consumer.jar")));}
    @Test void removalPlansExpireAndAreSingleUse()throws Exception {lifecycle(true);java.util.concurrent.atomic.AtomicLong time=new java.util.concurrent.atomic.AtomicLong(1000);Clock clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return Instant.ofEpochMilli(time.get());}};PluginLifecycle lifecycle=new PluginLifecycle(data,()->List.copyOf(runtime),()->true,clock);jar("example.jar","Example","");String expiredId=lifecycle.plan("Example","owner").get("planId").toString();time.addAndGet(300001);assertThrows(PluginLifecycle.Conflict.class,()->lifecycle.remove(expiredId,"owner",()->true));String planId=lifecycle.plan("Example","owner").get("planId").toString();lifecycle.remove(planId,"owner",()->true);assertThrows(PluginLifecycle.Conflict.class,()->lifecycle.remove(planId,"owner",()->true));assertThrows(IllegalArgumentException.class,()->lifecycle.restore("../outside","owner",()->true));}
    @Test void offlineRecoveryCancelsChangedQueuedJarWithoutChangingItsBytesAndRequiresBothLeases()throws Exception {PluginLifecycle lifecycle=lifecycle(true);Path target=jar("example.jar","Example","");String id=remove(lifecycle,"Example").get("removalId").toString();jar("example.jar","Example","description: manual drift\n");byte[] changed=Files.readAllBytes(target);try(var channel=java.nio.channels.FileChannel.open(root.resolve(".mcc-launcher/daemon.lock"),StandardOpenOption.WRITE);var guard=channel.lock(0,1,false)){assertThrows(java.nio.channels.OverlappingFileLockException.class,()->PluginMaintenanceBootstrap.cancelOffline(root,data,id));}assertEquals("cancelled",PluginMaintenanceBootstrap.cancelOffline(root,data,id).get("status"));assertArrayEquals(changed,Files.readAllBytes(target));assertEquals(0,PluginMaintenanceBootstrap.runOffline(root,data).get("removed"));}
}
